"""Explain final activation, C declarations and disabled API contracts."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1865': ('놀이 기구는 준비와 점검을 마친 뒤 시작 버튼을 눌러요. 검사 도구도 필요한 상태를 먼저 준비하고 마지막에 켜요.', 'KMSAN 시작 순서와 내부 함수 직접 호출을 이해합니다.', '작업 상태 준비→남은 블록 정리→안내 두 줄→검사 켜기의 네 단계를 적으세요.', ['kmsan_init_runtime은 부팅 때 KMSAN의 실행 상태를 준비하고 켜는 함수예요. runtime은 도구가 실행 중에 사용하는 기능과 상태를 가리키는 말이에요. KMSAN은 준비되지 않은 메모리 값을 사용하는 실수를 찾는 검사 도구예요.', '첫 호출은 kmsan_internal_task_create(current)예요. current는 지금 실행 중인 작업을 뜻해요. 원문 주석은 여기서 current가 초기 작업 init_task라는 전제를 밝혀요. 아무 작업에서나 같은 조건이라고 가정하지 않아요.', '다음 kmsan_memblock_discard는 부팅 과정에 보관해 둔 남은 블록을 모아 정리해요. 같은 크기 세 블록 중 하나를 데이터, 둘을 검사 정보로 연결하는 작업이 여기에 포함돼요.', '이후 시작 안내와 개발·오류 진단용 도구라는 안내를 두 번 출력해요. 마지막 문장 kmsan_enabled = true가 검사를 켜요. 아직 상태를 준비하기 전에 맨 처음부터 켜는 순서가 아니에요.', '이 함수는 이름에 internal이 들어간 내부 함수를 직접 호출해요. 일반 kmsan_task_create는 내부 작업 시작 표시→내부 함수→종료 표시를 감싸는 별도 함수예요. 이를 wrapper, 즉 다른 호출을 감싸는 함수라고 불러요.', '따라서 일반 wrapper에 있는 동작이 이 부팅 함수에도 자동으로 들어 있다고 생각하면 안 돼요. 종이에 호출 이름과 순서를 그대로 쓰고, 마지막 켜짐 표시까지 어떤 준비가 앞서는지 확인하세요. 이 순서 모형은 실제 커널 부팅을 실행한 결과와는 달라요.'], [('kmsan_enabled를 true로 만드는 문장은 어디에 있나요?', ['아무 준비도 하기 전 첫 문장이에요', '작업 상태 준비·블록 정리·안내 출력 뒤 마지막이에요'], '정답은 두 번째예요. 준비를 마친 뒤 켜는 순서예요. 안내가 출력됐다는 것과 이미 첫 단계부터 검사가 켜져 있었다는 것은 다른 말이에요.'), ('이 시작 함수는 일반 kmsan_task_create wrapper를 호출하나요?', ['아니요. kmsan_internal_task_create를 직접 호출해요', '네. 일반 wrapper의 모든 호출을 그대로 거쳐요'], '정답은 첫 번째예요. 실제 이름에 internal이 있어요. 이름이 비슷해도 호출하는 함수가 다르므로 wrapper의 앞뒤 처리가 자동으로 적용된다고 읽으면 안 돼요.')]), 'os1866': ('주문서에 적힌 주문 방법과 주방에서 실제 요리하는 과정은 달라요. 함수 선언은 부르는 방법을, 함수 본문은 수행 과정을 보여 줘요.', 'C 함수 선언과 구현, 구조체 전방 선언을 구별합니다.', 'void kmsan_task_create(struct task_struct *task);에서 이름·받는 값·반환 형식을 표시하세요.', ['include/linux/kmsan.h는 다른 커널 부분이 KMSAN을 호출할 때 보는 헤더예요. 헤더는 함께 사용할 이름과 형식을 알려 주는 파일이에요. 작업 생성, 메모리 할당, 장치 전송 같은 사건을 검사 도구에 알려 주는 함수들이 선언돼 있어요.', 'void kmsan_task_create(struct task_struct *task);는 함수 선언이에요. kmsan_task_create가 이름, 괄호 안이 받는 값의 형식, 앞의 void는 돌려주는 값이 없다는 뜻이에요. 끝의 세미콜론까지가 호출 형태를 알려 줘요.', '이 선언에는 중괄호로 감싼 실행 본문이 없어요. 켜짐 상태를 검사하는지, 언제 돌아가는지, 다른 함수를 어떤 순서로 부르는지는 구현을 읽어야 알아요. 인자 이름 하나가 모든 실행 조건을 알려 주지는 않아요.', '실제 구현은 hooks.c, core.c, shadow.c, init.c, report.c, instrumentation.c 등에 역할별로 나뉘어요. 선언에서 이름을 찾고 같은 이름의 본문으로 이동해 연결해서 읽는 것이 중요해요.', 'struct task_struct;는 그런 이름의 구조체가 있다는 사실만 먼저 알려 주는 전방 선언이에요. 내부 항목이 아직 없어도 struct task_struct *라는 포인터 형식은 선언할 수 있어요. 반면 task->어떤항목처럼 내부 값을 읽으려면 전체 정의가 필요해요.', '헤더 앞의 include guard는 같은 헤더 내용을 중복해서 처리하는 일을 막는 장치예요. CONFIG_KMSAN 조건은 검사 기능을 넣은 빌드인지에 따라 사용할 정의를 나눠요. 헤더는 실행 과정 자체만 담는 곳이 아니라 여러 파일이 같은 호출 규칙을 쓰게 하는 연결점이에요.'], [('함수 선언 한 줄만 보면 내부의 모든 조건문까지 알 수 있나요?', ['네. 인자 이름에 모든 실행 조건이 담겨 있어요', '아니요. 실제 본문도 읽어야 해요'], '정답은 두 번째예요. 선언은 호출 형태를 알려 주지만 if와 호출 순서는 본문에 있어요. 설명 주석과 구현을 함께 확인해야 해요.'), ('struct task_struct;만 먼저 선언해도 그 구조체를 가리키는 포인터 인자를 선언할 수 있나요?', ['네. 전체 내부 항목을 몰라도 포인터 선언은 가능해요', '아니요. 포인터를 선언하려면 항상 모든 내부 항목이 필요해요'], '정답은 첫 번째예요. 주소를 받을 수 있다는 선언과 내부 항목에 접근하는 것은 달라요. 실제 필드 접근이나 구조체 크기 계산에는 전체 정의가 필요해요.')]), 'os1867': ('받은 부탁에 아무 작업도 하지 않는 담당자가 있어도, 부탁할 내용을 계산하는 과정은 먼저 일어날 수 있어요. 빈 함수와 인자 계산은 별개예요.', '설정을 끈 빈 함수와 C 인자 평가를 구별합니다.', 'counter를 0으로 놓고 빈 함수의 order 자리에 ++counter를 넘기는 모형을 그리세요. 계산 후 값은 1이에요.', ['CONFIG_KMSAN은 커널을 만들 때 검사 기능을 넣을지 정하는 설정이에요. 설정이 없을 때 헤더는 같은 이름의 작은 대체 함수를 제공해요. 이런 대체 함수를 stub이라고 불러요.', 'kmsan_alloc_page의 대체 정의에는 중괄호 안에 아무 실행 문장이 없어요. 실제 페이지를 미준비 상태로 표시하는 검사 작업을 하지 않아요. 그래도 다른 코드에서는 같은 이름과 인자 형태로 부를 수 있어요.', '함수 호출에서는 인자로 쓸 표현을 계산해요. ++counter는 counter를 1 늘린 값을 전달한다는 뜻이에요. 처음 0이면 order 인자에 ++counter를 쓸 때 counter가 1이 돼요. 빈 본문이라는 이유로 이 의미가 사라지지 않아요.', '어떤 값을 바꾸는 이런 효과를 부수 효과라고 불러요. inline은 구현을 호출 위치에 펼쳐 넣는 등의 최적화를 가능하게 하는 표기이지, C에서 관찰할 수 있는 부수 효과를 마음대로 없애라는 지시는 아니에요.', '전처리 매크로 중에는 받은 표현을 결과 코드에 아예 넣지 않는 것도 있어요. 그 경우와 이 일반 함수 호출의 인자 평가를 혼동하지 마세요. 또한 여러 인자의 평가 순서는 이 예에서 다루지 않으므로 같은 변수를 여러 인자에서 동시에 바꾸는 예로 확장하지 않아요.', '설정을 끈 함수 호출 형태가 남아 있다고 실제 탐지도 남는 것은 아니에요. 이 예에서는 counter 증가라는 입력 계산과 빈 함수 본문을 따로 살펴요. 실제 커널 메모리를 바꾸는 실험 대신 값 하나의 종이 모형으로 이해할 수 있어요.'], [('counter가 0일 때 빈 inline 함수의 order 인자에 ++counter를 쓰면 증가 효과가 사라지나요?', ['네. 본문이 비었으니 counter는 반드시 0이에요', '아니요. C 의미상 인자가 평가되어 counter가 1이 돼요'], '정답은 두 번째예요. 인자 계산과 함수 본문은 구별돼요. 결과를 관찰하는 프로그램에서 빈 함수라는 이유로 증가 효과까지 없어지는 것은 아니에요.'), ('CONFIG_KMSAN이 없는 이 빈 kmsan_alloc_page 함수가 실제 페이지를 미준비로 표시하나요?', ['아니요. 검사 작업을 하는 본문이 없어요', '네. 활성 구현과 똑같이 모든 페이지를 검사해요'], '정답은 첫 번째예요. 같은 호출 형태를 유지하는 것과 검사 기능을 수행하는 것은 달라요. 인자는 평가될 수 있어도 빈 본문에 실제 검사 동작이 생기지는 않아요.')]), 'os1868': ('진행해도 된다는 신호가 언제나 검사 합격을 뜻하지는 않아요. 이 함수의 true는 페이지 반환 처리를 이어가라는 약속이에요.', '설정을 끈 함수의 반환값을 호출자 흐름과 연결합니다.', '대체 함수 true→호출자의 후속 처리→페이지 반환을 그리세요. 메모리 검사 합격이라는 이름은 붙이지 마세요.', ['KMSAN을 넣지 않은 빌드에서 kmsan_memblock_free_pages는 작은 대체 함수로 정의돼요. 받는 값은 페이지 블록과 order예요. order는 그 블록의 페이지 수를 나타내는 단계예요.', '대체 함수 본문은 return true 한 줄이에요. 검사 정보용 shadow와 origin을 위해 블록을 보류할 필요가 없기 때문이에요. 여기서 true는 데이터가 안전하다는 검사 결과가 아니라 다음 페이지 반환 처리를 진행할 수 있다는 결과예요.', '호출자는 결과가 false면 KMSAN이 페이지를 맡는 것으로 보고 돌아가요. true면 필요한 후속 처리를 거쳐 __free_pages_core로 페이지를 반환해요. 대체 함수 자체가 그 반환 함수를 직접 호출하는 것은 아니에요.', '검사를 넣은 실제 구현은 같은 order의 보관 자리가 비어 있을 때 첫 블록과 둘째 블록을 검사 정보 후보로 남겨 false를 반환해요. 셋째에 연결을 완성하면 true예요. 설정을 끈 대체 함수는 이런 보관 주기 없이 true를 줘요.', '선언의 __must_check는 반환값을 무시하지 말라는 컴파일러용 표시예요. 컴파일러는 소스를 실행 가능한 형태로 바꾸는 도구예요. 이 표시는 경고를 돕는 규칙이지 함수가 실제 모든 메모리 바이트를 검사했다는 인증이 아니에요.', '따라서 함수 이름이나 true라는 단어만으로 의미를 정하지 말고 호출자가 그 값을 어떻게 쓰는지 보세요. 이 경우에는 페이지를 보류할지 반환 경로를 이어갈지가 핵심이에요.'], [('KMSAN 설정을 끈 memblock 대체 함수가 반환하는 값은 무엇인가요?', ['언제나 false예요', 'true예요'], '정답은 두 번째예요. 원문 본문은 return true예요. 검사 정보용으로 페이지를 보류하지 않으므로 호출자가 후속 페이지 반환 처리를 이어갈 수 있어요.'), ('이 대체 함수의 true는 모든 바이트가 안전성 검사를 통과했다는 뜻인가요?', ['아니요. 호출자의 페이지 반환 흐름을 위한 값이에요', '네. 모든 바이트의 준비 상태를 검사했다는 뜻이에요'], '정답은 첫 번째예요. 이 설정에는 해당 검사 동작이 없어요. 반환값은 그 함수를 사용하는 코드의 약속에 따라 해석해야 해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_462.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
